/* ===================== BÀI 9 · RAM nội, bank và vùng bit ===================== */
/* Bài 9 · RAM nội, bank và vùng bit (AMTS-EMB-001-M03-L01, MC51-009) — sinh bởi tools/author/mcu8051/l09.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR9=[{"label":"Ví dụ: R0–R7 là 8 ô RAM 00H–07H","code":"; Ví dụ 1: R0-R7 của băng 0 chính là ô RAM 00H-07H\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     R0,#11H                 ; ghi ô 00H\n        MOV     R7,#77H                 ; ghi ô 07H\n        MOV     01H,#22H                ; ghi trực tiếp ô 01H = R1\n        MOV     A,07H                   ; đọc ô 07H: chính là R7\n        MOV     B,R1                    ; đọc R1: chính là ô 01H\n        SJMP    $\n        END\n","note":"Sau ba lệnh đầu, phần Bộ nhớ cho thấy ô 00H = 11H, 01H = 22H, 07H = 77H: R0, R1, R7 chính là ba ô đó. MOV A,07H (E5 07, 2 byte) và MOV A,R7 (EF, 1 byte) đọc cùng một ô. Tổng 7 chu kỳ máy tới SJMP $.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Đổi băng thanh ghi bằng RS1, RS0","code":"; Ví dụ 2: cùng tên R0, bốn ô khác nhau theo băng\n; Chip: AT89S52. RS1 = PSW.4, RS0 = PSW.3.\n        ORG     0000H\n        MOV     R0,#0A0H                ; RS1 RS0 = 00: băng 0, ô 00H\n        SETB    RS0                     ; 01: băng 1\n        MOV     R0,#0A1H                ; ô 08H\n        SETB    RS1                     ; 11: băng 3\n        MOV     R0,#0A3H                ; ô 18H\n        CLR     RS0                     ; 10: băng 2\n        MOV     R0,#0A2H                ; ô 10H\n        CLR     RS1                     ; 00: về băng 0\n        MOV     A,R0                    ; A = A0H (ô 00H)\n        SJMP    $\n        END\n","note":"Theo dõi PSW và phần Bộ nhớ: cùng lệnh MOV R0,#… (mã 78) lần lượt ghi ô 00H, 08H, 18H, 10H vì RS1 RS0 đổi 00 → 01 → 11 → 10. Đoán trước: sau CLR RS1, MOV A,R0 đọc ô nào? (00H, nên A = A0H.)","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Địa chỉ bit trong vùng 20H–2FH","code":"; Ví dụ 3: 128 bit có địa chỉ 00H-7FH nằm trong 20H-2FH\n; Địa chỉ bit = (byte - 20H) x 8 + số thứ tự bit.\n        ORG     0000H\n        SETB    00H                     ; bit 00H = 20H.0\n        SETB    0FH                     ; bit 0FH = 21H.7\n        SETB    2FH.7                   ; viết byte.bit: bit 7FH\n        CPL     20H.1                   ; bit 01H: 0 thành 1\n        MOV     A,20H                   ; A = 0000 0011B\n        MOV     C,21H.7                 ; C = bit 0FH = 1\n        SJMP    $\n        END\n","note":"Bốn lệnh bit đổi đúng bốn bit: ô 20H = 03H (bit 00H và 01H), 21H = 80H (bit 0FH), 2FH = 80H (bit 7FH). SETB 2FH.7 được dịch thành D2 7F, giống hệt SETB 7FH.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Số 07H là bit hay byte?","code":"; Ví dụ 4: cùng số 07H, lệnh quyết định bit hay byte\n; Chip: AT89S52.\n        ORG     0000H\n        MOV     R7,#00H                 ; ô byte 07H (R7) = 00H\n        SETB    07H                     ; lệnh bit: bit 07H = 20H.7\n        MOV     A,R7                    ; R7 vẫn bằng 00H\n        MOV     07H,#01H                ; lệnh byte: ghi ô 07H = R7\n        MOV     B,20H                   ; B = 80H\n        SJMP    $\n        END\n","note":"SETB 07H không đụng R7: nó bật bit 7 của ô 20H (ô 20H thành 80H). Chỉ lệnh byte MOV 07H,#01H mới ghi ô 07H, tức R7. Nhìn mã máy: D2 07 (lệnh bit) và 75 07 01 (lệnh byte).","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Ngăn xếp đè lên R0 của băng 1","code":"; Ví dụ 5: dùng băng 1 mà quên dời ngăn xếp\n; Chip: AT89S52. Sau reset SP = 07H.\n        ORG     0000H\n        MOV     PSW,#08H                ; RS0 = 1: dùng băng 1\n        MOV     R0,#5AH                 ; R0 băng 1 = ô 08H\n        MOV     A,#0C3H\n        PUSH    ACC                     ; SP = 08H, ghi C3H vào ô 08H\n        MOV     B,R0                    ; B = C3H, R0 đã bị đè\n        SJMP    $\n        END\n","note":"SP = 07H sau reset nên PUSH ACC tăng SP lên 08H rồi ghi C3H vào ô 08H, cũng là R0 của băng 1. Lệnh cuối đọc R0 ra B = C3H thay vì 5AH. Chương trình không báo lỗi gì: đây là lỗi logic, chỉ thấy khi xem Bộ nhớ.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Bit của SFR: P1.3 là bit 93H","code":"; Ví dụ 6: SFR có địa chỉ chia hết cho 8 có bit riêng\n; Chip: AT89S52. LED P1.x sáng khi chân = 0.\n        ORG     0000H\n        CLR     93H                     ; bit 93H = P1.3: LED P1.3 sáng\n        CLR     P1.0                    ; viết theo tên: bit 90H\n        MOV     A,#00H\n        SETB    0E7H                    ; bit E7H = ACC.7\n        MOV     C,P1.3                  ; đọc chân P1.3: C = 0\n        SJMP    $\n        END\n","note":"CLR 93H và CLR P1.0 là cùng một loại lệnh bit (mã C2): LED P1.3 và P1.0 sáng, P1 = F6H. SETB 0E7H bật ACC.7 nên A = 80H. MOV C,P1.3 đọc chân P1.3 = 0 vào cờ C.","dev":{"led":true},"fosc":12000000}];
const sim9=makeSim51(document.getElementById("m51-l9"),{id:"s9",presets:PR9,ram:256});
makeEx51(document.getElementById("ex-l9"),"l9",[{"t":"Chép sang băng 3","d":"<p>Chương trình phục vụ ngắt của bo dùng băng thanh ghi 3. Trước khi bật ngắt, hãy chép R0–R3 của <b>băng 0<\/b> sang R0–R3 của <b>băng 3<\/b> (R0 sang R0, R1 sang R1…). R0–R3 của băng 0 và mọi ô của băng 1 phải giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: R0–R3 băng 0 = <code>11H 22H 33H 44H<\/code> → R0–R3 băng 3 = <code>11H 22H 33H 44H<\/code>.<\/p>","start":"        ORG     0000H\n; Chép R0-R3 băng 0 sang R0-R3 băng 3\n; Viết code ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x00":17,"0x01":34,"0x02":51,"0x03":68,"0x18":238,"0x19":238,"0x1A":238,"0x1B":238,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}},"expect":{"iram":{"0x18":17,"0x19":34,"0x1A":51,"0x1B":68,"0x00":17,"0x01":34,"0x02":51,"0x03":68,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}}},{"setup":{"iram":{"0x00":0,"0x01":0,"0x02":0,"0x03":0,"0x18":238,"0x19":238,"0x1A":238,"0x1B":238,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}},"expect":{"iram":{"0x18":0,"0x19":0,"0x1A":0,"0x1B":0,"0x00":0,"0x01":0,"0x02":0,"0x03":0,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}}},{"setup":{"iram":{"0x00":255,"0x01":255,"0x02":255,"0x03":255,"0x18":238,"0x19":238,"0x1A":238,"0x1B":238,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}},"expect":{"iram":{"0x18":255,"0x19":255,"0x1A":255,"0x1B":255,"0x00":255,"0x01":255,"0x02":255,"0x03":255,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}}},{"setup":{"iram":{"0x00":128,"0x01":127,"0x02":1,"0x03":254,"0x18":238,"0x19":238,"0x1A":238,"0x1B":238,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}},"expect":{"iram":{"0x18":128,"0x19":127,"0x1A":1,"0x1B":254,"0x00":128,"0x01":127,"0x02":1,"0x03":254,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}}},{"setup":{"iram":{"0x00":90,"0x01":165,"0x02":60,"0x03":195,"0x18":238,"0x19":238,"0x1A":238,"0x1B":238,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}},"expect":{"iram":{"0x18":90,"0x19":165,"0x1A":60,"0x1B":195,"0x00":90,"0x01":165,"0x02":60,"0x03":195,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}}},{"setup":{"iram":{"0x00":16,"0x01":24,"0x02":8,"0x03":0,"0x18":238,"0x19":238,"0x1A":238,"0x1B":238,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}},"expect":{"iram":{"0x18":16,"0x19":24,"0x1A":8,"0x1B":0,"0x00":16,"0x01":24,"0x02":8,"0x03":0,"0x08":85,"0x09":85,"0x0A":85,"0x0B":85}}}]},"hints":["R0–R7 chỉ là tên. Băng 0 nằm ở ô 00H–07H, băng 3 ở ô nào? Tính 8 × số băng.","Không cần đổi RS1, RS0: lệnh MOV đích,nguồn với hai địa chỉ trực tiếp chép thẳng từ ô này sang ô kia.","Ô của băng 3 = ô cùng vị trí của băng 0 cộng 18H; MOV giữa hai địa chỉ trực tiếp chép mà không cần qua A. Không được ghi vào ô 08H."],"why":"Băng k chiếm 8 ô từ 8 × k: băng 3 là 18H–1FH. Chép bằng địa chỉ trực tiếp không phụ thuộc băng đang chọn, nên không cần đổi RS1, RS0 và không lo quên đổi lại. Bộ thử 5 bắt lỗi ghi nhầm vào băng 1 (08H–0BH)."},{"t":"Hai cờ từ ô 30H","d":"<p>Ô <code>30H<\/code> chứa một số đo 8 bit. Đặt hai cờ trong vùng bit: cờ <code>00H<\/code> (bit 0 của ô 20H) bằng bit 7 của ô 30H, cờ <code>01H<\/code> (bit 1 của ô 20H) bằng bit 0 của ô 30H. Sáu bit còn lại của ô <code>20H<\/code> là cờ của phần khác trong chương trình, phải giữ nguyên. Ô 30H giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 81H<\/code>, <code>20H = 00H<\/code> → <code>20H = 03H<\/code>.<\/p>","start":"        ORG     0000H\n; Bit 00H = bit 7 của ô 30H\n; Bit 01H = bit 0 của ô 30H\n; Viết code ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":129,"0x20":0}},"expect":{"iram":{"0x20":3,"0x30":129}}},{"setup":{"iram":{"0x30":0,"0x20":255}},"expect":{"iram":{"0x20":252,"0x30":0}}},{"setup":{"iram":{"0x30":128,"0x20":0}},"expect":{"iram":{"0x20":1,"0x30":128}}},{"setup":{"iram":{"0x30":1,"0x20":164}},"expect":{"iram":{"0x20":166,"0x30":1}}},{"setup":{"iram":{"0x30":126,"0x20":95}},"expect":{"iram":{"0x20":92,"0x30":126}}},{"setup":{"iram":{"0x30":255,"0x20":60}},"expect":{"iram":{"0x20":63,"0x30":255}}}]},"hints":["Ô 30H nằm ngoài vùng 20H–2FH nên không có địa chỉ bit: SETB 30H.7 hay MOV C,30H.7 đều báo lỗi dịch.","Chép ô 30H vào A. Thanh ghi A (ACC, địa chỉ E0H) định địa chỉ bit được: ACC.7, ACC.0.","Cờ C là chỗ trung gian để chép từng bit: đọc bit của ACC vào C rồi ghi C ra địa chỉ bit đích. Không ghi cả byte 20H."],"why":"Chỉ ô 20H–2FH và các SFR có địa chỉ chia hết cho 8 mới có bit riêng. Chép số đo vào A để dùng các bit ACC.n, rồi chuyển từng bit qua C bằng MOV bit,C: lệnh này chỉ đổi đúng một bit, sáu cờ còn lại của ô 20H giữ nguyên (bộ thử 2 và 5)."},{"t":"Bốn cờ trong 8 chu kỳ","d":"<p>Code mẫu muốn chép 4 bit thấp của ô <code>30H<\/code> vào 4 cờ <code>21H.0<\/code>–<code>21H.3<\/code> (bit 08H–0BH) nhưng có lỗi và chậm. Hãy sửa để: (1) bit 0–3 của ô 21H bằng bit 0–3 của ô 30H; (2) bit 4–7 của ô 21H, ô 30H và các ô 22H–25H giữ nguyên; (3) toàn chương trình chạy không quá <b>8 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>12 byte<\/b>.<\/p><p>Ví dụ: <code>30H = 05H<\/code>, <code>21H = 00H<\/code> → <code>21H = 05H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,30H                   ; A = ô 30H\n        MOV     C,ACC.0\n        MOV     21H,C                   ; ý định: bit 0 của ô 21H\n        MOV     C,ACC.1\n        MOV     22H,C\n        MOV     C,ACC.2\n        MOV     23H,C\n        MOV     C,ACC.3\n        MOV     24H,C\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":5,"0x21":0,"0x22":90,"0x23":60,"0x24":129,"0x25":126}},"expect":{"iram":{"0x21":5,"0x30":5,"0x22":90,"0x23":60,"0x24":129,"0x25":126}}},{"setup":{"iram":{"0x30":15,"0x21":240,"0x22":90,"0x23":60,"0x24":129,"0x25":126}},"expect":{"iram":{"0x21":255,"0x30":15,"0x22":90,"0x23":60,"0x24":129,"0x25":126}}},{"setup":{"iram":{"0x30":0,"0x21":255,"0x22":90,"0x23":60,"0x24":129,"0x25":126}},"expect":{"iram":{"0x21":240,"0x30":0,"0x22":90,"0x23":60,"0x24":129,"0x25":126}}},{"setup":{"iram":{"0x30":240,"0x21":10,"0x22":90,"0x23":60,"0x24":129,"0x25":126}},"expect":{"iram":{"0x21":0,"0x30":240,"0x22":90,"0x23":60,"0x24":129,"0x25":126}}},{"setup":{"iram":{"0x30":166,"0x21":89,"0x22":90,"0x23":60,"0x24":129,"0x25":126}},"expect":{"iram":{"0x21":86,"0x30":166,"0x22":90,"0x23":60,"0x24":129,"0x25":126}}},{"setup":{"iram":{"0x30":57,"0x21":195,"0x22":90,"0x23":60,"0x24":129,"0x25":126}},"expect":{"iram":{"0x21":201,"0x30":57,"0x22":90,"0x23":60,"0x24":129,"0x25":126}}}],"maxCyc":8,"maxBytes":12},"hints":["Chạy code mẫu từng bước và xem phần Bộ nhớ: MOV 21H,C đổi bit nào? Địa chỉ bit 21H nằm trong byte (21H div 8) + 20H.","Sửa thành 21H.0…21H.3 thì đúng nhưng tốn 1 + 4 × 3 = 13 chu kỳ. Xử lý cả 4 bit một lúc bằng lệnh byte sẽ nhanh hơn.","Lệnh byte xử lý 4 bit một lúc: cần một mặt nạ cho số đo, một mặt nạ cho phần phải xóa của ô 21H, rồi ghép hai phần."],"why":"Trong lệnh MOV bit,C, số 21H là địa chỉ BIT: bit 21H = bit 1 của byte 24H, nên code mẫu ghi nhầm vào ô 24H (bộ thử 6). Bốn lệnh bit đúng tốn 13 chu kỳ; dùng mặt nạ trên cả byte (AND với 0FH, AND ô 21H với F0H, rồi OR) chỉ cần 5 chu kỳ + 2 chu kỳ SJMP $ = 7 chu kỳ, mã 11 byte."}]);

makeQuiz("quiz9","score9",[{"q": "Sau lệnh MOV PSW,#10H, lệnh MOV R2,#5 ghi số 5 vào ô RAM nào?", "o": ["02H", "0AH", "12H", "1AH"], "a": 2, "e": "10H = 0001 0000B nên RS1 = 1, RS0 = 0: băng 2, bắt đầu ở 10H. R2 là ô 10H + 2 = 12H. 02H là R2 của băng 0, chỉ đúng khi RS1 RS0 = 00."}, {"q": "Lệnh SETB 0BH đổi cái gì trong RAM trong?", "o": ["Bit 3 của ô 21H", "Ô 0BH (R3 của băng 1) thành 01H", "Bit 0 của ô 2BH", "Bit 3 của ô 20H"], "a": 0, "e": "SETB là lệnh bit nên 0BH là địa chỉ bit: (21H − 20H) × 8 + 3 = 0BH, tức 21H.3. Lệnh bit không ghi cả byte nên ô 0BH không bị đụng tới."}, {"q": "Đoạn MOV R7,#00H rồi SETB 07H rồi MOV A,R7 (băng 0) chạy xong thì A bằng bao nhiêu?", "o": ["80H", "00H", "01H", "07H"], "a": 1, "e": "SETB 07H bật bit 07H, là bit 7 của ô 20H; R7 (ô byte 07H) vẫn bằng 00H. 80H là giá trị mới của ô 20H, không phải của R7."}, {"q": "Chương trình không đổi SP, chọn băng 1 rồi gọi PUSH ACC. Byte của A được cất vào đâu?", "o": ["Ô 07H, là R7 của băng 0", "Ô 08H, cũng là R0 của băng 1", "Ô 30H, đầu vùng dùng chung", "Ô 80H, đầu vùng RAM cao"], "a": 1, "e": "Sau reset SP = 07H; PUSH tăng SP trước rồi mới ghi, nên byte đầu tiên vào ô 08H, đè lên R0 của băng 1. Cần MOV SP,#2FH (hoặc cao hơn) ở đầu chương trình."}, {"q": "Dòng nào làm trình dịch kiểu Keil A51 báo lỗi?", "o": ["SETB 2FH.7", "SETB P1.3", "SETB ACC.7", "SETB 30H.0"], "a": 3, "e": "Chỉ ô 20H–2FH và SFR có địa chỉ chia hết cho 8 mới có bit riêng. 2FH.7 là bit 7FH, P1.3 là bit 93H, ACC.7 là bit E7H; ô 30H không có địa chỉ bit."}]);

